private fun lucide(name: String, stroke: Float, filled: Boolean, vararg paths: String): ImageVector {
    val paint = SolidColor(Color.Black)
    val builder = ImageVector.Builder(
        name = if (filled) "$name.filled" else "$name.$stroke",
        defaultWidth = 24.dp,
        defaultHeight = 24.dp,
        viewportWidth = 24f,
        viewportHeight = 24f,
    )
    for (path in paths) {
        builder.addPath(
            pathData = addPathNodes(path),
            fill = if (filled) paint else null,
            stroke = paint,
            strokeLineWidth = stroke,
            strokeLineCap = StrokeCap.Round,
            strokeLineJoin = StrokeJoin.Round,
        )
    }
    return builder.build()
}
